import React, { useState } from 'react';
import SolarMaintenanceForm from './SolarMaintenanceForm';

const SolarMaintenancePanel = ({ addMaintenanceRecord, setAdminStats }) => {
  const [submissionSuccess, setSubmissionSuccess] = useState(false);

  const handleSubmitSuccess = () => {
    setSubmissionSuccess(true);
    // Reset success message after 3 seconds
    setTimeout(() => {
      setSubmissionSuccess(false);
    }, 3000);

    // Update dashboard stats
    setAdminStats(prev => ({
      ...prev,
      totalInspections: prev.totalInspections + 1,
      pendingTasks: prev.pendingTasks + 1
    }));
  };

  return (
    <div className="solar-maintenance">
      <h2>Solar Panel Maintenance Check</h2>
      <p>Fill out the form below to submit a maintenance check for a solar panel.</p>

      {submissionSuccess && (
        <div className="success-message">
          Maintenance check submitted successfully! The record has been added to maintenance history.
        </div>
      )}

      <SolarMaintenanceForm 
        addMaintenanceRecord={addMaintenanceRecord} 
        onSubmitSuccess={handleSubmitSuccess}
      />
    </div>
  );
};

export default SolarMaintenancePanel;
